async triggerPipeline(pipelineId: number, options: TriggerOptions = {}): Promise<AgentResponse> {
  // ADO pins a run to a branch via resources.repositories.self.refName;
  // 'self' is the pipeline's own YAML repo.
  const body: Record<string, unknown> = {
    resources: {
      repositories: {
        // Must be a FULL git ref (refs/heads/...), not a bare branch name, or ADO runs the default branch.
        self: { refName: options.branch ? `refs/heads/${options.branch}` : 'refs/heads/main' },
      },
    },
  };

  // POST to /runs both creates AND queues the run in one call - there is no separate 'start'.
  const response = await fetch(
    `${this.baseUrl}/pipelines/${pipelineId}/runs?api-version=7.0`,
    {
      method: 'POST',
      headers: { Authorization: this.authHeader, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    }
  );

  const run = await response.json();
  return {
    success: true,
    // run.id is the handle every later poll/cancel needs; _links.web.href is the browser URL ADO returns.
    data: { runId: run.id, state: run.state, url: run._links.web.href },
    message: `Pipeline run #${run.id} triggered successfully`,
  };
}

async waitForCompletion(
  pipelineId: number,
  runId: number,
  options: { timeout?: number; pollInterval?: number } = {}
): Promise<AgentResponse> {
  const timeout = options.timeout || 30 * 60 * 1000;      // 30 minutes default
  const pollInterval = options.pollInterval || 30 * 1000; // 30 seconds default
  const startTime = Date.now();

  // Bound the total wait so a hung run can't block forever.
  while (Date.now() - startTime < timeout) {
    const run = await this.getRunStatus(pipelineId, runId);
    // Null = transient API failure; bail rather than loop on a dead handle.
    if (!run) return { success: false, data: {}, errors: ['Failed to get pipeline status'] };

    // 'completed' is ADO's only terminal state; run.result then tells us HOW it ended.
    if (run.state === 'completed') {
      // state says it finished; result (succeeded|failed|canceled) says the outcome.
      const success = run.result === 'succeeded';
      return {
        success,
        data: { runId: run.id, result: run.result, url: run.webUrl },
        message: `Pipeline ${success ? 'succeeded' : 'failed'}`,
      };
    }
    await this.sleep(pollInterval);
  }
  // Fell out of the loop = never reached 'completed' within the timeout window.
  return { success: false, data: {}, errors: [`Timeout waiting for pipeline after ${timeout / 1000}s`] };
}

async getArtifacts(pipelineId: number, runId: number): Promise<PipelineArtifact[]> {
  const response = await fetch(
    `${this.baseUrl}/pipelines/${pipelineId}/runs/${runId}/artifacts?api-version=7.0`,
    { headers: { Authorization: this.authHeader } }
  );

  // No artifacts or no access -> return empty rather than throw, so the caller degrades gracefully.
  if (!response.ok) return [];

  const data = await response.json();
  return data.value.map((artifact: any) => ({
    name: artifact.name,
    // signedContent.url is a short-lived signed link ADO mints on demand - use promptly, don't cache.
    downloadUrl: artifact.signedContent.url,
    size: artifact.size,
  }));
}

async cancelRun(pipelineId: number, runId: number): Promise<AgentResponse> {
  const response = await fetch(
    // Target the run itself; PATCH = partial update of the existing run, not a new POST.
    `${this.baseUrl}/pipelines/${pipelineId}/runs/${runId}?api-version=7.0`,
    {
      method: 'PATCH',
      headers: { Authorization: this.authHeader, 'Content-Type': 'application/json' },
      // Sets intent only; ADO tears the run down async, so it won't stop instantly.
      body: JSON.stringify({ state: 'canceling' }),
    }
  );

  return { success: true, data: { runId }, message: `Pipeline run ${runId} cancelled` };
}
